// ============================================================
// 1) app/actions.ts —— Server Action（运行在服务端）
// ============================================================
'use server'

export type FormState = {
  status: 'idle' | 'success' | 'error'
  message: string
  errors: Record<string, string>
}

// useActionState 要求 action 的第一个参数是「上一次的 state」
export async function subscribe(
  _prevState: FormState,
  formData: FormData
): Promise<FormState> {
  const name = String(formData.get('name') ?? '').trim()
  const email = String(formData.get('email') ?? '').trim()

  // 服务端校验：永远不能省略，Server Action 是公开端点
  const errors: Record<string, string> = {}
  if (!name) errors.name = '姓名不能为空'
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.email = '邮箱格式不正确'

  if (Object.keys(errors).length > 0) {
    return { status: 'error', message: '请修正表单中的错误', errors }
  }

  // 模拟数据库 / 第三方 API 的耗时
  await new Promise((r) => setTimeout(r, 800))

  // 真实项目中可在这里调用 revalidatePath('/') 刷新缓存
  return { status: 'success', message: `${name} 订阅成功！`, errors: {} }
}


// ============================================================
// 2) app/components/SubmitButton.tsx —— 客户端组件
//    useFormStatus 让按钮自己感知所属 form 的提交状态
// ============================================================
'use client'

import { useFormStatus } from 'react-dom'

export default function SubmitButton({ label = '提交' }: { label?: string }) {
  const { pending } = useFormStatus() // 必须是 <form> 的后代组件

  return (
    <button
      type="submit"
      disabled={pending}
      aria-busy={pending}
      style={{
        padding: '8px 16px',
        opacity: pending ? 0.6 : 1,
        cursor: pending ? 'not-allowed' : 'pointer',
      }}
    >
      {pending ? '提交中…' : label}
    </button>
  )
}


// ============================================================
// 3) app/subscribe/page.tsx —— 客户端组件（持有表单状态）
// ============================================================
'use client'

import { useActionState } from 'react'
import { subscribe, type FormState } from '../actions'
import SubmitButton from '../components/SubmitButton'

const initialState: FormState = { status: 'idle', message: '', errors: {} }

export default function SubscribePage() {
  const [state, formAction, isPending] = useActionState(subscribe, initialState)

  return (
    <form action={formAction} style={{ display: 'grid', gap: 12, maxWidth: 360 }}>
      <h1 style={{ margin: 0 }}>订阅周报</h1>

      {/* 提交结果提示：role="status" 让屏幕阅读器播报 */}
      {state.message && (
        <p role="status" style={{ color: state.status === 'error' ? 'crimson' : 'green' }}>
          {state.message}
        </p>
      )}

      <label style={{ display: 'grid', gap: 4 }}>
        姓名
        <input name="name" placeholder="你的名字" />
        {state.errors.name && <small style={{ color: 'crimson' }}>{state.errors.name}</small>}
      </label>

      <label style={{ display: 'grid', gap: 4 }}>
        邮箱
        <input name="email" type="email" placeholder="you@example.com" />
        {state.errors.email && <small style={{ color: 'crimson' }}>{state.errors.email}</small>}
      </label>

      {/* isPending 来自 useActionState，可用于禁用整张表单 */}
      <fieldset disabled={isPending} style={{ border: 0, padding: 0, margin: 0 }}>
        <SubmitButton label="订阅" />
      </fieldset>
    </form>
  )
}

